import * as T from './vendor/three.module.js';
export function createQuests(scene){
 const base={boxOpen:false,bridge:false,cartMoved:false,parts:[false,false,false],complete:false};let state={...base,parts:[...base.parts]};try{const s=JSON.parse(localStorage.getItem('little-house-stage2'));if(s?.version===1){for(const k of ['boxOpen','bridge','cartMoved','complete'])state[k]=s[k]===true;state.parts=Array.from({length:3},(_,i)=>s.parts?.[i]===true);state.parts[0]&&=state.boxOpen;state.parts[1]&&=state.bridge;state.parts[2]&&=state.cartMoved;state.complete&&=state.parts.every(Boolean);}}catch{}
 const save=()=>{try{localStorage.setItem('little-house-stage2',JSON.stringify({...state,version:1}));}catch{}};
 const mat=(color,extra={})=>new T.MeshStandardMaterial({color,roughness:.7,...extra});const oak=mat('#c8a171'),paper=mat('#d5b997'),lidMat=mat('#aa7661'),gold=mat('#d0ab65',{metalness:.65,roughness:.3}),blue=mat('#87b6b2'),dark=mat('#644e39'),cream=mat('#f3e5c3');const boxG=new T.BoxGeometry(1,1,1);
 function mesh(g,m,x,y,z,sx=1,sy=1,sz=1,parent=scene){const o=new T.Mesh(g,m);o.position.set(x,y,z);o.scale.set(sx,sy,sz);o.castShadow=true;o.receiveShadow=true;parent.add(o);return o;}const box=(m,x,y,z,w,h,d,parent=scene)=>mesh(boxG,m,x,y,z,w,h,d,parent);
 function group(x,y,z){const g=new T.Group();g.position.set(x,y,z);scene.add(g);return g;}
 const mx=-.65,mz=2.72;const match=group(mx,0,mz);box(paper,0,.035,0,.6,.045,.75,match);for(let side of [-1,1])box(paper,side*.29,.115,0,.035,.19,.75,match);box(paper,0,.115,-.37,.6,.19,.035,match);const lid=box(lidMat,0,.235,0,.65,.05,.8,match);const lidLabel=box(cream,0,.265,0,.44,.007,.45,match); // Label uses modeled borders, with no placeholder text.
 // A ruler with engraved divisions, ready to become a sloping bridge.
 const ruler=group(-2.5,.09,-.4);const ramp=box(oak,0,0,0,.48,.06,1.65,ruler);for(let i=0;i<31;i++){box(dark,-.18+(i%5===0?.035:0),.034,-.76+i*.05,i%5===0?.15:.08,.004,.009,ruler);if(i%5===0)box(gold,.13,.035,-.76+i*.05,.025,.004,.013,ruler);}
 const book=group(-1.75,0,-2.2);for(let i=0;i<4;i++){box([lidMat,blue,oak,dark][i],0,.06+i*.12,0,1.14,.1,.74,book);box(cream,0,.071+i*.12,.01,1.08,.07,.67,book);}box(gold,0,.487,0,.96,.01,.57,book);
 // A cardboard tunnel under the sofa. The cart physically blocks its entrance.
 const tx=3,tz=.7;box(paper,3.08,.015,tz,.93,.025,.82);for(let z of [tz-.42,tz+.42])box(paper,3.08,.145,z,.94,.29,.028);box(paper,3.53,.145,tz,.035,.29,.86);box(paper,3.08,.3,tz,.95,.025,.86);
 const cart=group(2.55,.04,tz);box(blue,0,.1,0,.18,.17,.75,cart);box(oak,0,.205,0,.24,.045,.82,cart);for(let z of [-.27,.27])for(let x of [-.105,.105]){const w=mesh(new T.CylinderGeometry(.062,.062,.035,12),dark,x,.034,z,1,1,1,cart);w.rotation.z=Math.PI/2;}box(gold,0,.265,.19,.04,.085,.22,cart);
 // Three tiny components with distinct silhouettes and glow.
 function part(i,x,y,z){const g=group(x,y,z);if(i===0){const ring=mesh(new T.TorusGeometry(.065,.016,6,20),gold,0,0,0,1,1,1,g);ring.rotation.x=Math.PI/2;for(let k=0;k<10;k++){const a=k/10*Math.PI*2;const o=box(gold,Math.cos(a)*.075,0,Math.sin(a)*.075,.034,.035,.034,g);o.rotation.y=-a;}}else if(i===1){mesh(new T.OctahedronGeometry(.075),mat('#a3d8c5',{metalness:.2,emissive:'#67c6ac',emissiveIntensity:.5}),0,0,0,1,1,1,g);}else{for(let k=0;k<6;k++)mesh(new T.TorusGeometry(.048,.009,5,16),gold,0,-.04+k*.016,0,1,1,1,g).rotation.x=Math.PI/2;}const light=new T.PointLight(['#f8d48b','#92e0c9','#f7c78b'][i],.08,.7);g.add(light);return g;}
 const pieces=[part(0,mx,.077,mz),part(1,-1.75,.565,-2.2),part(2,3.25,.087,tz)];
 // The restoration mechanism is a little brass observatory at floor level.
 const device=group(.65,0,2.9);mesh(new T.CylinderGeometry(.31,.34,.065,32),dark,0,.045,0,1,1,1,device);mesh(new T.CylinderGeometry(.27,.28,.035,32),gold,0,.09,0,1,1,1,device);const orb=mesh(new T.SphereGeometry(.105,24,16),mat('#b4d6c7',{transparent:true,opacity:.6,roughness:.1,emissive:'#73c6b0',emissiveIntensity:.2}),0,.29,0,1,1,1,device);for(let k=0;k<3;k++){const o=mesh(new T.TorusGeometry(.19+k*.025,.008,6,40),gold,0,.27,0,1,1,1,device);o.rotation.set(k*.7,.5+k,0);}const slots=[];for(let i=0;i<3;i++){const a=i*2.094;slots.push(mesh(new T.SphereGeometry(.036,12,8),dark,Math.sin(a)*.22,.13,Math.cos(a)*.22,1,1,1,device));}const beacon=new T.PointLight('#c5f2db',0,5);beacon.position.set(.65,.6,2.9);scene.add(beacon);
 function sync(){lid.position.z=state.boxOpen?-.9:0;lidLabel.position.z=lid.position.z;if(state.bridge){ruler.position.set(-1.75,.249,-1.1);ruler.rotation.x=Math.atan(.48/1.5);}else{ruler.position.set(-2.5,.09,-.4);ruler.rotation.x=0;}cart.position.z=state.cartMoved?1.65:tz;pieces.forEach((p,i)=>p.visible=!state.parts[i]);slots.forEach((s,i)=>s.material=state.parts[i]?blue:dark);beacon.intensity=state.complete?1.5:0;orb.material.emissiveIntensity=state.complete?1.5:.2;}
 function ground(x,z){if(x>=-2.31&&x<=-1.19&&z>=-2.57&&z<=-1.83)return .48;if(state.bridge&&Math.abs(x+1.75)<.245&&z>=-1.88&&z<=-.32)return Math.max(0,Math.min(.48,(-z-.35)/1.5*.48));return 0;}
 function blocked(x,z,mini,fromY=0){const r=mini?.05:.18;if(Math.abs(x-mx)<.32+r&&Math.abs(z-mz)<.4+r){if(!mini||!state.boxOpen)return true;if(Math.abs(x-mx)>.255||z<mz-.31)return true;}
 if(Math.abs(x+1.75)<.57+r&&Math.abs(z+2.2)<.37+r&&(!mini||fromY<.39))return true;
 if(mini){if(x>2.58&&x<3.61&&(Math.abs(z-(tz-.42))<.05||Math.abs(z-(tz+.42))<.05))return true;if(Math.abs(x-3.53)<.065&&Math.abs(z-tz)<.46)return true;if(!state.cartMoved&&Math.abs(x-2.55)<.15&&Math.abs(z-tz)<.49)return true;}return false;}
 const dist=(p,x,z)=>Math.hypot(p.x-x,p.z-z);
 function context(p,mini){if(!state.parts[0]&&dist(p,mx,mz)<(mini?.6:1.25)){if(!state.boxOpen)return {id:'box',label:'拉開盒蓋',message:mini?'盒蓋比你還重。':'木盒的蓋子可以滑動。'};if(mini&&dist(p,mx,mz)<.28)return {id:'part0',label:'拾取小齒輪'};return {id:'lookbox',label:'查看木盒'};}
 if(!state.parts[1]&&dist(p,-1.75,-1.25)<(mini?1.3:1.7)){if(!state.bridge)return {id:'bridge',label:'架起尺橋',message:mini?'這把尺太長了，現在的你搬不動。':'書堆與地板之間，還缺一條路。'};if(mini&&dist(p,-1.75,-2.2)<.3&&ground(p.x,p.z)>.4)return {id:'part1',label:'拾取光晶'};return {id:'lookbridge',label:'查看尺橋'};}
 if(!state.parts[2]&&dist(p,2.55,tz)<(mini?1.1:1.55)){if(!state.cartMoved)return {id:'cart',label:'推開小車',message:mini?'車輪擋住了紙盒入口。':'小車停在紙盒前，車身並不重。'};if(mini&&dist(p,3.25,tz)<.28)return {id:'part2',label:'拾取彈簧'};return {id:'lookcart',label:'查看紙盒'};}
 if(dist(p,.65,2.9)<(mini?.65:1.15))return {id:'device',label:state.complete?'欣賞裝置':'啟動裝置'};return null;}
 function interact(p,mini){const c=context(p,mini);if(!c)return {message:'靠近可以操作的物件，再試試看。'};if(['box','bridge','cart'].includes(c.id)){if(mini)return {message:c.message+' 試著換一種尺度。'};state[c.id==='box'?'boxOpen':c.id==='bridge'?'bridge':'cartMoved']=true;sync();save();return {message:{box:'盒蓋滑開了。裡面有一個細小的金色零件。',bridge:'尺已靠上書堆。刻度現在像是一格一格的步道。',cart:'小車移到一旁，紙盒前方露出低矮的入口。'}[c.id]};}
 if(c.id.startsWith('part')){const i=Number(c.id.slice(-1));if(state.parts[i])return {message:'這個零件已經收好了。'};state.parts[i]=true;sync();save();return {message:['收好了小齒輪。','光晶散發著淡淡綠光。','彈簧已放進零件袋。'][i]};}
 if(c.id==='device'){if(state.complete)return {message:'三個零件各就各位，裝置仍在緩緩運轉。你可以繼續探索。'};if(!state.parts.every(Boolean))return {message:'裝置上有三個不同形狀的空槽。目前還有空位。'};state.complete=true;sync();save();return {complete:true,message:'齒輪轉動，光晶亮起，彈簧輕輕一跳。恢復裝置啟動了！你已完成客廳探索，仍可自由切換大小。'};}
 return {message:{lookbox:'木盒裡的齒輪比指甲還小。',lookbridge:'書堆頂端有一顆發亮的晶體。尺橋沿著斜坡連接地板與書堆。',lookcart:'紙盒裡藏著一個小彈簧。入口只比鈕扣高一點。'}[c.id]};}
 function update(time){pieces.forEach((p,i)=>{p.rotation.y=time*.7+i;p.children.forEach(o=>{if(o.isPointLight)o.intensity=.08+Math.sin(time*2)*.025;});});if(state.complete)orb.rotation.y=time;}
 function reset(){state={...base,parts:[false,false,false]};sync();save();}
 sync();return {ground,blocked,context,interact,update,reset,get state(){return {...state,parts:[...state.parts]};}};
}
